package com.franco.desco.adapter.in.web.fieldtrip;import com.franco.desco.application.fieldtrip.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.fieldtrip.FieldTripModels;import org.springframework.stereotype.Component;import java.time.Instant;
@Component public class FieldTripWebMapper{public FieldTripCommands.ListTrips list(int p,int t,String estado,Integer motivo,Instant desde,Instant hasta){return new FieldTripCommands.ListTrips(new PageRequest<>(p,t,new FieldTripCommands.Filter(estado,motivo,desde,hasta),null,null));}public FieldTripCommands.Program command(FieldTripRequests.Program q){return new FieldTripCommands.Program(q.motivoSalidaId(),q.fechaHoraProgramada(),q.descripcion(),q.participantes().stream().map(x->new FieldTripCommands.ParticipantInput(x.empleadoId(),x.funcion(),x.esResponsable())).toList());}public FieldTripCommands.Update command(Long id,FieldTripRequests.Update q){return new FieldTripCommands.Update(id,q.motivoSalidaId(),q.fechaHoraProgramada(),q.descripcion(),q.participantes().stream().map(x->new FieldTripCommands.ParticipantInput(x.empleadoId(),x.funcion(),x.esResponsable())).toList());}public FieldTripResponses.Summary response(FieldTripModels.Summary x){return new FieldTripResponses.Summary(x.salidaCampoId(),x.motivoSalidaId(),x.motivo(),x.fechaHoraProgramada(),x.fechaHoraSalidaReal(),x.fechaHoraRetornoReal(),x.descripcion(),x.estadoProceso(),x.estado(),x.participantes(),x.recursosProgramados());}public FieldTripResponses.Detail response(FieldTripModels.Detail d){return new FieldTripResponses.Detail(response(d.salida()),d.motivoCodigo(),d.participantes().stream().map(x->new FieldTripResponses.Participant(x.salidaParticipanteId(),x.empleadoId(),x.codigoEmpleado(),x.nombres(),x.apellidoPaterno(),x.apellidoMaterno(),x.funcion(),x.esResponsable(),x.estado())).toList(),d.recursos().stream().map(x->new FieldTripResponses.Resource(x.recursoProgramadoId(),x.bienInventarioId(),x.codigoPatrimonial(),x.bienNombre(),x.suministroId(),x.suministroCodigo(),x.suministroNombre(),x.unidadMedida(),x.cantidadProgramada(),x.observacion(),x.estado(),x.cantidadEjecutada())).toList(),d.bienes().stream().map(x->new FieldTripResponses.Asset(x.salidaBienId(),x.bienInventarioId(),x.codigoPatrimonial(),x.nombre(),x.fechaHoraEntrega(),x.fechaHoraDevolucion(),x.estadoEntrega(),x.estadoDevolucion(),x.observacion(),x.estado())).toList(),d.visitas().stream().map(x->new FieldTripResponses.Visit(x.visitaTecnicaId(),x.salidaParticipanteId(),x.predioId(),x.predioCodigo(),x.predioNombre(),x.fechaHoraInicio(),x.fechaHoraFin(),x.estadoProceso(),x.estado())).toList());}}
